def f2(inp):
    h,w=len(inp),len(inp[0])
    from collections import Counter
    c=Counter(x for r in inp for x in r)
    bg=c.most_common(1)[0][0]
    col=None
    for k,x in c.items():
        if k==bg: continue
        if any(all(y==k for y in r) for r in inp) or any(all(inp[r][y]==k for y in range(w)) for r in range(h)):
            col=k; break
    out=[row[:] for row in inp]
    for i,r in enumerate(inp):
        if all(x==col for x in r):
            for j in range(w): out[i][j]=2
    for j in range(w):
        if all(inp[i][j]==col for i in range(h)):
            for i in range(h): out[i][j]=2
    return out
